import React from "react";
import { UserProvider } from "./UserContext";
import AuthProvider from "./provider/AuthProvider";
import Routes from "./routes/routes";
import './App.css'
import UpdateStatusOnClose from "./Worker/close_page";



function App(){
  return(
    <AuthProvider>
        <UserProvider>
          <UpdateStatusOnClose />
          <Routes />
        </UserProvider>
    </AuthProvider>
  )
}


export default App;
